#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

int main(void)
{
    size_t len = 4096;
    void *mem = mmap(NULL, len, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        return 1;
    }
    memcpy(mem, "shellcode placeholder", 21);
    /* 이후 mprotect(mem, len, PROT_READ|PROT_EXEC)로 실행권한 부여 가능 */
    printf("mapped at %p: %s\n", mem, (char *)mem);
    munmap(mem, len);
    return 0;
}

